namespace ReFix.Hub {
 public sealed class ModuleManifest {
  public string Id{get;set;} public string Name{get;set;} public string Description{get;set;} public string Version{get;set;} public string Kind{get;set;} public string EntryPoint{get;set;} public string PackageUrl{get;set;} public string Sha256{get;set;} public string Preview{get;set;} public string MinHubVersion{get;set;} public string EnableArgument{get;set;} public string DisableArgument{get;set;} public string StatusArgument{get;set;}
  public ModuleManifest(){Kind="process";Preview="notes";MinHubVersion="1.0.0";EnableArgument="--enable";DisableArgument="--disable";StatusArgument="--status";}
  public void Validate(){
   if(!Regex.IsMatch(Id??"","^[a-z][a-z0-9-]{0,63}$")||IsDevice(Id))throw new InvalidDataException("Invalid module ID.");
   if(!Regex.IsMatch(Version??"","^[0-9]{1,5}\\.[0-9]{1,5}\\.[0-9]{1,5}(\\.[0-9]{1,5})?$")||!ValidVersion(Version))throw new InvalidDataException("Invalid version.");
   if(string.IsNullOrWhiteSpace(Name)||Name.Length>160|| (Description??"").Length>4000)throw new InvalidDataException("Invalid module description.");
   if(Kind!="process"&&Kind!="fix")throw new InvalidDataException("Unknown module kind.");
   PackageSafety.Relative(EntryPoint);if(!EntryPoint.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Entry point must be an executable.");
   if(Preview!="mixer"&&Preview!="notes"&&Preview!="fix")throw new InvalidDataException("Unknown preview.");
   if(!ValidVersion(MinHubVersion)||new Version(MinHubVersion)>new Version(ProductInfo.Version))throw new InvalidDataException("Unsupported minimum hub version.");
   if(!string.IsNullOrEmpty(Sha256)&&!Regex.IsMatch(Sha256,"^[a-fA-F0-9]{64}$"))throw new InvalidDataException("Invalid SHA256.");
   if(!string.IsNullOrEmpty(PackageUrl))ValidateUrl(PackageUrl);
   if(Kind=="fix")foreach(string arg in new[]{EnableArgument,DisableArgument,StatusArgument})if(string.IsNullOrWhiteSpace(arg)||arg.Length>128||!Regex.IsMatch(arg,"^--?[a-zA-Z0-9-]+$"))throw new InvalidDataException("Invalid fix argument.");
  }
  static bool ValidVersion(string v){System.Version parsed;return System.Version.TryParse(v,out parsed);}
  internal static bool IsDevice(string value){return Regex.IsMatch(value??"","^(con|prn|aux|nul|com[0-9]|lpt[0-9])($|\\.)",RegexOptions.IgnoreCase);}
  public static void ValidateUrl(string value){Uri u;if(!Uri.TryCreate(value,UriKind.Absolute,out u)||u.Scheme!="https"||u.Host!="github.com"||u.Port!=443||u.UserInfo!=""||u.Query!=""||u.Fragment!=""||!Regex.IsMatch(u.AbsolutePath,"^/KirrieD/HUB-ReFIXwin11/releases/download/[A-Za-z0-9._-]+/[A-Za-z0-9._-]+\\.zip$"))throw new InvalidDataException("Package URL must be a release asset in KirrieD/HUB-ReFIXwin11.");}
 }
 public sealed class CatalogDocument {public int SchemaVersion{get;set;} public List<ModuleManifest> Modules{get;set;}}
 public sealed class ModuleView:INotifyPropertyChanged {
  public ModuleManifest Manifest{get;set;} string state="NO",detail="",installed="";bool busy;
  public string State{get{return state;}set{state=value;Notify("State");}} public string Detail{get{return detail;}set{detail=value;Notify("Detail");}} public string InstalledVersion{get{return installed;}set{installed=value;Notify("InstalledVersion");}} public bool IsBusy{get{return busy;}set{busy=value;Notify("IsBusy");}}
  public event PropertyChangedEventHandler PropertyChanged;void Notify(string p){var h=PropertyChanged;if(h!=null)h(this,new PropertyChangedEventArgs(p));}
 }
 public static class PackageSafety {
  public const long MaxArchive=64L*1024*1024,MaxExpanded=256L*1024*1024;
  public static void Relative(string path){if(string.IsNullOrWhiteSpace(path)||path.Length>200||Path.IsPathRooted(path)||path.Contains(":")||path.Contains("\\")||path.IndexOfAny(Path.GetInvalidPathChars())>=0)throw new InvalidDataException("Unsafe package path.");foreach(var part in path.Split('/'))if(part==""||part=="."||part==".."||part.EndsWith(".")||part.EndsWith(" ")||part.IndexOfAny(Path.GetInvalidFileNameChars())>=0||ModuleManifest.IsDevice(part))throw new InvalidDataException("Unsafe package path.");}
  public static string Inside(string root,string path){Relative(path);string prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string full=Path.GetFullPath(Path.Combine(root,path.Replace('/',Path.DirectorySeparatorChar)));if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Package path escaped root.");return full;}
  public static void Extract(string archive,string root){
   if(new FileInfo(archive).Length>MaxArchive)throw new InvalidDataException("Archive too large.");Directory.CreateDirectory(root);long total=0;var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
   using(var zip=ZipFile.OpenRead(archive)){if(zip.Entries.Count>2048)throw new InvalidDataException("Too many archive entries.");foreach(var e in zip.Entries){string relative=e.FullName.TrimEnd('/');string dest=Inside(root,relative);if(!seen.Add(dest))throw new InvalidDataException("Duplicate archive entry.");int mode=(e.ExternalAttributes>>16)&0xF000;if(mode==0xA000||(e.ExternalAttributes&0x400)!=0)throw new InvalidDataException("Archive links are forbidden.");total=checked(total+e.Length);if(total>MaxExpanded)throw new InvalidDataException("Expanded package too large.");if(e.FullName.EndsWith("/")){Directory.CreateDirectory(dest);continue;}Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var input=e.Open())using(var output=new FileStream(dest,FileMode.CreateNew)){byte[] buffer=new byte[32768];long count=0;int n;while((n=input.Read(buffer,0,buffer.Length))>0){count+=n;if(count>e.Length||count>MaxExpanded)throw new InvalidDataException("Archive entry exceeds bounds.");output.Write(buffer,0,n);}if(count!=e.Length)throw new InvalidDataException("Archive entry truncated.");}}}
  }
  public static string Hash(string path){using(var hash=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 }
 public sealed class InstalledRecord {public ModuleManifest Manifest{get;set;} public Dictionary<string,string> Files{get;set;}}
 public sealed class ModuleManager:IDisposable {
  const string CatalogUrl="https://raw.githubusercontent.com/KirrieD/HUB-ReFIXwin11/main/catalog/catalog.json";
  readonly string root,bundle,cache;readonly CatalogDocument bundledCatalog;readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);readonly object catalogGate=new object();List<ModuleView> modules=new List<ModuleView>();bool disposed;
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=1024*1024,RecursionLimit=32};}
  public IList<ModuleView> Modules{get{lock(catalogGate){return new List<ModuleView>(modules).AsReadOnly();}}} public event EventHandler Changed;
  public ModuleManager(string dataRoot,string bundledCatalogPath){root=Path.GetFullPath(dataRoot);bundle=Path.GetFullPath(bundledCatalogPath);cache=Path.Combine(root,"catalog-cache.json");Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"modules"));Directory.CreateDirectory(Path.Combine(root,"state"));
   CatalogDocument doc=null;string error="";if(File.Exists(cache))try{doc=ReadCatalog(File.ReadAllText(cache));}catch(Exception e){error="Cached catalogue: "+e.Message;}
   try{bundledCatalog=ReadCatalog(File.ReadAllText(bundle));}catch(Exception e){error+=" Bundled catalogue: "+e.Message;}
   Apply(MergeCatalog(doc));foreach(var v in modules){if(error!="")v.Detail=error;RefreshState(v);} }
  CatalogDocument MergeCatalog(CatalogDocument incoming){
   // Never replace a newer shipped/current module with stale cached or remote metadata.
   var selected=new Dictionary<string,ModuleManifest>(StringComparer.Ordinal);
   Action<ModuleManifest> consider=m=>{ModuleManifest old;if(!selected.TryGetValue(m.Id,out old)||new Version(m.Version)>=new Version(old.Version))selected[m.Id]=m;};
   if(bundledCatalog!=null)foreach(var m in bundledCatalog.Modules)consider(m);
   foreach(var view in Modules)consider(view.Manifest);
   if(incoming!=null)foreach(var m in incoming.Modules)consider(m);
   // Equal-version metadata must describe the verified archive shipped beside HUB.
   if(bundledCatalog!=null)foreach(var m in bundledCatalog.Modules){ModuleManifest current;if(!selected.TryGetValue(m.Id,out current)||new Version(m.Version)!=new Version(current.Version))continue;try{string package=FindBundle(m);if(package!=null&&!string.IsNullOrEmpty(m.Sha256)&&string.Equals(PackageSafety.Hash(package),m.Sha256,StringComparison.OrdinalIgnoreCase))selected[m.Id]=m;}catch(IOException){}catch(UnauthorizedAccessException){}}
   return new CatalogDocument{SchemaVersion=1,Modules=selected.Values.ToList()};
  }
  static CatalogDocument ReadCatalog(string text){text=text.TrimStart('\uFEFF');if(text.Length>1024*1024)throw new InvalidDataException("Catalogue too large.");var d=Json().Deserialize<CatalogDocument>(text);if(d==null||d.SchemaVersion!=1||d.Modules==null||d.Modules.Count>200)throw new InvalidDataException("Invalid catalogue schema.");var ids=new HashSet<string>();foreach(var m in d.Modules){if(m==null)throw new InvalidDataException("Null module.");m.Validate();if(!ids.Add(m.Id))throw new InvalidDataException("Duplicate module ID.");}return d;}
  void Apply(CatalogDocument d){lock(catalogGate){var next=new List<ModuleView>();foreach(var m in d.Modules){var view=modules.FirstOrDefault(v=>v.Manifest.Id==m.Id)??new ModuleView();view.Manifest=m;next.Add(view);}modules=next;}}
  void Signal(){var h=Changed;if(h!=null)h(this,EventArgs.Empty);}
  Task Work(Action action){return Task.Run(async()=>{await gate.WaitAsync().ConfigureAwait(false);try{if(disposed)throw new ObjectDisposedException("ModuleManager");action();}finally{gate.Release();Signal();}});}
  public Task RefreshCatalogAsync(){return Work(()=>{try{string text=Encoding.UTF8.GetString(Download(CatalogUrl,1024*1024,false));var doc=MergeCatalog(ReadCatalog(text));Atomic(cache,Json().Serialize(doc));Apply(doc);foreach(var v in modules){v.Detail="Catalogue refreshed.";RefreshState(v);}}catch(Exception e){foreach(var v in modules)v.Detail="Remote catalogue unavailable; local catalogue retained. "+e.Message;throw;}});}
  static byte[] Download(string url,long max,bool package){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(url);request.Timeout=15000;request.ReadWriteTimeout=15000;request.UserAgent="ReFIXHub/1.0";request.AllowAutoRedirect=false;
   // Release asset redirects are followed only to GitHub's HTTPS asset host.
   for(int redirect=0;redirect<4;redirect++){using(var response=(HttpWebResponse)request.GetResponse()){if((int)response.StatusCode>=300&&(int)response.StatusCode<400){Uri next=new Uri(new Uri(request.RequestUri.AbsoluteUri),response.Headers["Location"]);if(!package||next.Scheme!="https"||next.Port!=443||next.UserInfo!=""||!(next.Host=="release-assets.githubusercontent.com"||next.Host=="github.com"))throw new InvalidDataException("Unexpected download redirect.");request=(HttpWebRequest)WebRequest.Create(next);request.Timeout=15000;request.ReadWriteTimeout=15000;request.AllowAutoRedirect=false;request.UserAgent="ReFIXHub/1.0";continue;}if(response.ContentLength>max)throw new InvalidDataException("Download too large.");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){var timer=Stopwatch.StartNew();var buffer=new byte[32768];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(timer.ElapsedMilliseconds>30000)throw new TimeoutException("Download exceeded total time limit.");if(output.Length+n>max)throw new InvalidDataException("Download too large.");output.Write(buffer,0,n);}return output.ToArray();}}}throw new IOException("Too many redirects.");}
  public void VerifyLocalPackage(ModuleView v){CheckView(v);v.Manifest.Validate();string package=FindBundle(v.Manifest);if(package==null)throw new FileNotFoundException("Verified bundled mixer package is unavailable; migration will not download.");if(string.IsNullOrEmpty(v.Manifest.Sha256)||!string.Equals(PackageSafety.Hash(package),v.Manifest.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Local package SHA256 mismatch.");}
  public Task InstallAsync(ModuleView v){return InstallPackageAsync(v,false);}
  public Task InstallLocalAsync(ModuleView v){return InstallPackageAsync(v,true);}
  Task InstallPackageAsync(ModuleView v,bool localOnly){return Work(()=>{v.IsBusy=true;string stage=null,temp=null;try{CheckView(v);RefreshState(v);if(v.State=="ON"||HasLiveIdentity(v))throw new InvalidOperationException("Stop the module before installing or updating.");v.Manifest.Validate();if(string.IsNullOrEmpty(v.Manifest.Sha256))throw new InvalidDataException("No verified package hash is published.");string package=FindBundle(v.Manifest);if(package==null){if(localOnly)throw new FileNotFoundException("Verified bundled package is unavailable; local-only install will not download.");if(string.IsNullOrEmpty(v.Manifest.PackageUrl))throw new FileNotFoundException("Bundled/local package is not available; no release download is published.");ModuleManifest.ValidateUrl(v.Manifest.PackageUrl);temp=Path.Combine(root,"download-"+Guid.NewGuid().ToString("N")+".zip");File.WriteAllBytes(temp,Download(v.Manifest.PackageUrl,PackageSafety.MaxArchive,true));package=temp;}if(!string.Equals(PackageSafety.Hash(package),v.Manifest.Sha256,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Package SHA256 mismatch.");string parent=Path.Combine(root,"modules",v.Manifest.Id);Directory.CreateDirectory(parent);stage=Path.Combine(parent,".stage-"+Guid.NewGuid().ToString("N"));PackageSafety.Extract(package,stage);if(!File.Exists(PackageSafety.Inside(stage,v.Manifest.EntryPoint)))throw new InvalidDataException("Package entry point missing.");var record=new InstalledRecord{Manifest=v.Manifest,Files=new Dictionary<string,string>()};foreach(var file in Directory.GetFiles(stage,"*",SearchOption.AllDirectories)){string rel=file.Substring(stage.Length+1).Replace('\\','/');if(rel=="installed.json")throw new InvalidDataException("Reserved package metadata.");record.Files.Add(rel,PackageSafety.Hash(file));}Atomic(Path.Combine(stage,"installed.json"),Json().Serialize(record));string target=Path.Combine(parent,v.Manifest.Version),backup=target+".backup-"+Guid.NewGuid().ToString("N");bool moved=false,promoted=false;try{if(Directory.Exists(target)){Directory.Move(target,backup);moved=true;}Directory.Move(stage,target);promoted=true;stage=null;Atomic(Path.Combine(parent,"current.json"),Json().Serialize(v.Manifest.Version));}catch{if(promoted&&Directory.Exists(target))Directory.Delete(target,true);if(moved)Directory.Move(backup,target);throw;}if(moved)Directory.Delete(backup,true);v.Detail="Installed verified package. Start explicitly to activate.";RefreshState(v);}catch(Exception e){RefreshState(v);v.Detail="Install failed: "+e.Message;throw;}finally{if(stage!=null&&Directory.Exists(stage))Directory.Delete(stage,true);if(temp!=null&&File.Exists(temp))File.Delete(temp);v.IsBusy=false;}});}
  string FindBundle(ModuleManifest m){foreach(string baseDir in new[]{Path.GetDirectoryName(bundle),Path.GetDirectoryName(Path.GetDirectoryName(bundle)),AppDomain.CurrentDomain.BaseDirectory}){if(baseDir==null)continue;string p=Path.Combine(baseDir,"packages",m.Id+"-"+m.Version+".zip");if(File.Exists(p))return p;}return null;}
  static void Atomic(string path,string text){string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,text,new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  void CheckView(ModuleView v){if(v==null||!modules.Contains(v))throw new InvalidOperationException("Unknown module.");}
  InstalledRecord Installed(ModuleView v,out string directory){v.Manifest.Validate();string parent=Path.Combine(root,"modules",v.Manifest.Id),current=Path.Combine(parent,"current.json");directory=null;if(!File.Exists(current))return null;string version=Json().Deserialize<string>(File.ReadAllText(current));if(!Regex.IsMatch(version??"","^[0-9]{1,5}\\.[0-9]{1,5}\\.[0-9]{1,5}(\\.[0-9]{1,5})?$"))throw new InvalidDataException("Invalid installed version.");directory=Path.Combine(parent,version);string metadata=Path.Combine(directory,"installed.json");if(new FileInfo(metadata).Length>1024*1024)throw new InvalidDataException("Installed metadata too large.");var record=Json().Deserialize<InstalledRecord>(File.ReadAllText(metadata));if(record==null||record.Manifest==null||record.Files==null||record.Files.Count>2048)throw new InvalidDataException("Invalid installed metadata.");record.Manifest.Validate();if(record.Manifest.Id!=v.Manifest.Id||record.Manifest.Version!=version||!record.Files.ContainsKey(record.Manifest.EntryPoint))throw new InvalidDataException("Installed identity mismatch.");long installedBytes=0;foreach(var f in record.Files){string file=PackageSafety.Inside(directory,f.Key);installedBytes=checked(installedBytes+new FileInfo(file).Length);if(installedBytes>PackageSafety.MaxExpanded)throw new InvalidDataException("Installed files exceed package bound.");if(!Regex.IsMatch(f.Value??"","^[a-fA-F0-9]{64}$")||!File.Exists(file)||!string.Equals(PackageSafety.Hash(file),f.Value,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Installed file verification failed: "+f.Key);if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Installed links forbidden.");}return record;}
  public Task RefreshStatesAsync(){return Work(()=>{foreach(var v in modules)if(!v.IsBusy)RefreshState(v);});}
  void RefreshState(ModuleView v){v.InstalledVersion="";try{string dir;var record=Installed(v,out dir);if(record==null){v.State="NO";v.InstalledVersion="";return;}v.InstalledVersion=record.Manifest.Version;v.State="OFF";if(record.Manifest.Kind=="fix"){var result=Fix(record.Manifest,dir,record.Manifest.StatusArgument);VerifyFix(result,record.Manifest.Id);v.State=GetString(result,"state");}else{var identity=Identity(record.Manifest,dir);if(identity!=null){var reply=Pipe(record.Manifest.Id,"status");VerifyIdentity(reply,identity,record.Manifest.Id);v.State="ON";}}}catch(Exception e){v.State=v.InstalledVersion==""?"NO":"OFF";v.Detail="State verification failed: "+e.Message;}}
  string StateFile(string id){return Path.Combine(root,"state",id+".json");}
  Dictionary<string,object> ReadObject(string text){if(text==null||text.Length>8192)throw new InvalidDataException("Invalid status response.");return Json().Deserialize<Dictionary<string,object>>(text);}
  Dictionary<string,object> Identity(ModuleManifest m,string dir){string path=StateFile(m.Id);if(!File.Exists(path))return null;if(new FileInfo(path).Length>8192)throw new InvalidDataException("Oversized process state.");var identity=ReadObject(File.ReadAllText(path));int pid;long ticks;if(GetString(identity,"id")!=m.Id||!int.TryParse(GetString(identity,"pid"),out pid)||!long.TryParse(GetString(identity,"startedUtc"),out ticks))throw new InvalidDataException("Invalid process identity.");try{using(var process=Process.GetProcessById(pid)){if(process.HasExited||process.StartTime.ToUniversalTime().Ticks!=ticks)return null;string expected=PackageSafety.Inside(dir,m.EntryPoint);if(!string.Equals(process.MainModule.FileName,expected,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Process executable identity mismatch.");return identity;}}catch(ArgumentException){return null;}}
  bool HasLiveIdentity(ModuleView v){try{string dir;var record=Installed(v,out dir);return record!=null&&Identity(record.Manifest,dir)!=null;}catch{return File.Exists(StateFile(v.Manifest.Id));}}
  static string GetString(Dictionary<string,object> d,string key){object value;return d!=null&&d.TryGetValue(key,out value)?Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture):"";}
  static void VerifyIdentity(Dictionary<string,object> reply,Dictionary<string,object> identity,string id){if(GetString(reply,"id")!=id||GetString(reply,"state")!="ON"||GetString(reply,"protocol")!="1"||GetString(reply,"pid")!=GetString(identity,"pid")||GetString(reply,"startedUtc")!=GetString(identity,"startedUtc"))throw new IOException("Module control response identity mismatch.");}
  Dictionary<string,object> Pipe(string id,string command){using(var pipe=new NamedPipeClientStream(".",ModuleRuntime.PipeName(id,root),PipeDirection.InOut,PipeOptions.Asynchronous)){pipe.Connect(400);byte[] bytes=Encoding.UTF8.GetBytes(command+"\n");var write=pipe.BeginWrite(bytes,0,bytes.Length,null,null);using(write.AsyncWaitHandle){if(!write.AsyncWaitHandle.WaitOne(600))throw new TimeoutException("Module control write timed out.");pipe.EndWrite(write);}using(var output=new MemoryStream()){var deadline=Stopwatch.StartNew();byte[] b=new byte[1];while(output.Length<8192){if(deadline.ElapsedMilliseconds>1200)throw new TimeoutException("Module control exceeded total reply time.");var read=pipe.BeginRead(b,0,1,null,null);int count;using(read.AsyncWaitHandle){if(!read.AsyncWaitHandle.WaitOne(600))throw new TimeoutException("Module control reply timed out.");count=pipe.EndRead(read);}if(count==0)break;if(b[0]==10)break;output.WriteByte(b[0]);}if(output.Length>=8192)throw new InvalidDataException("Oversized pipe reply.");return ReadObject(Encoding.UTF8.GetString(output.ToArray()));}}}
  static void VerifyFix(Dictionary<string,object> result,string id){if(GetString(result,"id")!=id||GetString(result,"protocol")!="1"||(GetString(result,"state")!="ON"&&GetString(result,"state")!="OFF"))throw new InvalidDataException("Invalid fix status response.");}
  Dictionary<string,object> Fix(ModuleManifest m,string dir,string argument){using(var p=new Process()){p.StartInfo=new ProcessStartInfo(PackageSafety.Inside(dir,m.EntryPoint),argument){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=dir};p.StartInfo.EnvironmentVariables["REFIX_DATA_ROOT"]=root;p.Start();var stdout=Task.Run(()=>BoundedRead(p.StandardOutput));var stderr=Task.Run(()=>BoundedRead(p.StandardError));if(!p.WaitForExit(4000)){try{p.Kill();}catch{}throw new TimeoutException("Fix command timed out.");}if(!Task.WaitAll(new Task[]{stdout,stderr},1000))throw new TimeoutException("Fix output timed out.");if(p.ExitCode!=0)throw new IOException("Fix command failed: "+stderr.Result);return ReadObject(stdout.Result.Trim());}}
  static string BoundedRead(StreamReader reader){var result=new StringBuilder();char[] buffer=new char[1024];int n;while((n=reader.Read(buffer,0,buffer.Length))>0){if(result.Length+n>8192)throw new InvalidDataException("Command output too large.");result.Append(buffer,0,n);}return result.ToString();}
  public Task StartAsync(ModuleView v){return Command(v,"start");}public Task StopAsync(ModuleView v){return Command(v,"stop");}public Task ShowAsync(ModuleView v){return Command(v,"show");}
  Task Command(ModuleView v,string command){return Work(()=>{v.IsBusy=true;try{CheckView(v);string dir;var record=Installed(v,out dir);if(record==null)throw new InvalidOperationException("Install the module first.");var m=record.Manifest;if(m.Kind=="fix"){if(command=="show")throw new InvalidOperationException("This fix has no module window.");var result=Fix(m,dir,command=="start"?m.EnableArgument:m.DisableArgument);VerifyFix(result,m.Id);}else{var identity=Identity(m,dir);if(command=="start"&&identity==null){var info=new ProcessStartInfo(PackageSafety.Inside(dir,m.EntryPoint),"--background"){UseShellExecute=false,WorkingDirectory=dir};info.EnvironmentVariables["REFIX_DATA_ROOT"]=root;using(var p=Process.Start(info)){}var startup=Stopwatch.StartNew();while(startup.ElapsedMilliseconds<5000){Thread.Sleep(100);RefreshState(v);if(v.State=="ON")break;}if(v.State!="ON")throw new IOException("Module started but did not verify control-pipe health. "+v.Detail);}else{if(identity==null)throw new InvalidOperationException("Module is not running.");VerifyIdentity(Pipe(m.Id,"status"),identity,m.Id);var acknowledgement=Pipe(m.Id,command=="stop"?"stop":"show");if(GetString(acknowledgement,"ok")!="True")throw new IOException("Module rejected control command.");if(command=="stop"){try{using(var stopping=Process.GetProcessById(int.Parse(GetString(identity,"pid")))){if(stopping.StartTime.ToUniversalTime().Ticks.ToString(System.Globalization.CultureInfo.InvariantCulture)==GetString(identity,"startedUtc")&&!stopping.WaitForExit(3000))throw new IOException("Module acknowledged stop but has not exited.");}}catch(ArgumentException){}}}}RefreshState(v);if(command=="stop"&&v.State=="ON")throw new IOException("Module remains active after stop.");if(command=="start"&&v.State!="ON")throw new IOException("Module did not verify active state.");v.Detail=command=="stop"?"Stopped.":"Module health verified.";}catch(Exception e){RefreshState(v);v.Detail="Action failed: "+e.Message;throw;}finally{v.IsBusy=false;}});}
  public void Dispose(){disposed=true;}
 }
